
export class DREvent {
    constructor(par,  fun, array) {
        var self=this
        this.type="DREvent";
        this.dinBody=null
        this.par=par
        this.fun=fun;
        this.array=array;
        this._metodType=null;

        this.rPar=par.rPar;
        this.dCont=new DCont(this.par.dCont);
        this.ols=this.par.ols;

        this.panel=new DPanel(this.dCont)
        this.panel.width=this.rPar.whScane
        this.panel.height=this.rPar.whScane
        this.panel.alpha=0

        this.mScaneA=par.par.menu.mScaneA
        this.galBody=par.par.menu.mScaneA.galBody;

        this.drButton=new DRButton(this)
        this.drMenu=new DRMenu(this)




        this.creat=function(o){
            return this.par.wScane.creat(this.rPar.objStart)
        }


        this.sBody=function(){
            
        }



        var rP={x:0, y:0}


        var bStart=false;




        this.stop=function(){
            if(this.dinBody==null)return
            if (dcmParam.mobile == false) {
                document.removeEventListener('mouseup', self.mouseup);
            } else {
                document.removeEventListener('touchend', self.mouseup);
            }
            dcmParam.removeFunMove(self.mousemove);

            this.dinBody.link=this.par.drScane.getPicBody(this.dinBody)
            
            this.galBody.drag(this.par.wScane.array)

            this.par.par.aBody=this.dinBody;
            self.drButton.activMouse=true;    
            this.par.par.restart()
            this.dinBody=null;

        }




        this.start=function(p,e){
            if(this.dinBody!=null)return 
            this.dinBody=this.creat(this.rPar.objStart)
            this.dinBody.addPoint(p)

            if(self.dinBody.object.type==="Text"){
                self.dinBody.object.text='';
                this.stop()
                return
            }

            if(self.dinBody.object.type!=="LineDrag"){
                this.dinBody.addPoint(p)
            }

            if(self.dinBody.object.type=="BitMap"){
                this.dinBody.piclink='data:image/png;base64,'
            }

           
            
            self.drButton.activMouse=false
            this.drButton.aBody=this.dinBody;

            self.par.par.menu.mIBlok.mibLinsAnd.setBody(this.dinBody);

            self.mousemove(e)
            if (dcmParam.mobile == false) {
                document.addEventListener('mouseup', self.mouseup);
            } else {
                document.addEventListener('touchend', self.mouseup);
            }
            dcmParam.addFunMove(self.mousemove);
        }

        this.pStart={x:0, y:0}
        this.pS11={x:0, y:0}
        this.mousedown=function(e){
            if(self.dinBody!=null)return 
            self.getPoint(e,self.pS11)    
            self.start(self.getPoint(e,self.pStart),e)
        }

        this.point={x:0, y:0}
        var pf
        this.mouseup=function(e){
            if(self.dinBody!=undefined){
                if( self.dinBody.object.type=="Line" || 
                    self.dinBody.object.type=="Rect" || 
                    self.dinBody.object.type=="Сircle"||
                    self.dinBody.object.type=="LineDrag"||
                    self.dinBody.object.type=="BitMap"
                    ){
                    self.mousemove(e)
                    self.stop();
                    return
                }
            } 



            if(self.dinBody!=undefined){
                if( self.dinBody.object.type=="Line3"){
                    if(self.dinBody.array.length==3){
                        self.mousemove(e)
                        self.stop();
                        return
                    }
                    self.dinBody.addPoint(self.point)
                    self.drButton.setArrBody(self.drButton.sArray)
                }
            }           

            if(self.dinBody!=undefined){
                if( self.dinBody.object.type=="Line2"){
                    
                    if(e.button!=0){ 
                        self.dinBody.array.pop()                        
                        self.stop();
                        self.drButton.setArrBody(self.drButton.sArray)
                        return 
                    }


                   // self.getPoint(e,self.point)                   
                    
                    if(self.point.x==self.pStart.x && self.point.y==self.pStart.y){
                       
                        self.dinBody.addPoint(self.point)
                        self.mousemove(e)
                        self.stop(); 
                        self.drButton.setArrBody(self.drButton.sArray)
                        return
                    }
                   
                    pf=self.dinBody.array[self.dinBody.array.length-2];
                    if(self.point.x==pf.x && self.point.y==pf.y){  }else{
                        
                        self.dinBody.addPoint(self.point)
                        self.drButton.setArrBody(self.drButton.sArray)
                    }

                    
                } 
            }   

            
        }

        this.mP={x:0, y:0}

        var ppp, bbb
        this.mousemove = function(e) {

            

            if(self.dinBody==undefined){
                self.stop();
                return
            }

            
            bbb=true

            self.getPoint(e,self.mP)            
            
            
            if(self.dinBody.object.type=="LineDrag"){
                bbb=false
                ppp=self.dinBody.array[self.dinBody.array.length-1]
                
                if(self.mP.x==ppp.x && self.mP.y==ppp.y){  }else
                {                    
                    self.dinBody.addPoint(self.mP.x, self.mP.y)
                }
                
            }

            if(bbb){
                self.dinBody.setPFinal(self.mP)
                self.drButton.draw()
            }
            
            fun("dragScane");
        }


        if (dcmParam.mobile == false) {
            this.panel.div.addEventListener('mousedown', self.mousedown);           
        } else {
            this.panel.div.addEventListener('touchstart', self.mousedown);
        }


        var rect1;
        var ss 
        this.getPoint=function(e,p,b){
            if(p==undefined)p=rP
            if(e && e.target){
                rect1 = self.panel.div.getBoundingClientRect();
            }  
            ss=self.panel.getScaleScane()
              
            if (dcmParam.mobile==false) {
                p.x = e.clientX;
                p.y = e.clientY;
            }else{              
                p.x = e.touches[0].clientX;
                p.y = e.touches[0].clientY;
            }
            p.y-=rect1.y;
            p.y/=ss;
            p.x-=rect1.x;
            p.x/=ss; 
            if(b==undefined){
                if(self.ols.privazka==true)self.privazkaPP(p)
                self.privazkaPP2(p) 
            }
                     
            return p;
        }

        this.privazkaPP=function(p){                       
            p.x=Math.round(p.x/10)*10
            p.y=Math.round(p.y/10)*10
        } 

        this.privazkaPP2=function(p){
            if(self.dinBody!=null){
                if(Math.abs(p.x-self.pStart.x)<5){
                    if(Math.abs(p.y-self.pStart.y)<5){
                        p.x=self.pStart.x
                        p.y=self.pStart.y                        
                    }
                }
            }
        }
        var hhh, www;
        this.mousewheel = function (e) {            
           
            var delta=-1;
            var p=e.delta
            if(e.wheelDelta==undefined){
                p=e.wheelDelta
            }

            if(e.delta)if(e.delta<0)delta=1;
            if(e.deltaY)if(e.deltaY<0)delta=1;
            if(e.detail)if(e.detail<0)delta=1;

            if(e.wheelDelta!=undefined){
                if(e.wheelDelta>0)delta=-1;
                else delta=1;
            }
            p=delta;

           
            let bb=self.par.par.menu.mIBlok.mibLinsAnd.body
            if(bb){
                
                let s=bb.object.lineSah+p
                if(s<2)s=2;
                if(s>50)s=50;


                bb.object.lineSah=s; 
                self.par.par.menu.mIBlok.mibLinsAnd.setBody(bb);
                self.par.par.menu.mIBlok.mibLinsAnd.drag() 
                if(bb.object.type=="Text"){
                     self.drButton.korText()
                }
            } 
        }


        if (dcmParam.mobile == false) {                      
            this.par.par.dCont.div.addEventListener('mousewheel', this.mousewheel)
            this.par.par.dCont.div.addEventListener("DOMMouseScroll", this.mousewheel);                  
        } 


        this.plusPic =function(base64){
            let img=new Image();
            let sahLoad=self.par.par.sahLoad
            
            img.onload = () => {
                
                if(sahLoad!==self.par.par.sahLoad)return

                let s=img.naturalWidth/200;
                if(s<img.naturalHeight/200)s=img.naturalHeight/200;
                if(s<1)s=1;
                let ww=img.naturalWidth/s;
                let hh=img.naturalHeight/s;
                
                

                self.par.par.metodType="BitMap";

                var ddd=self.creat(self.rPar.objStart)



                ddd.addPoint({x:100-ww/2,y:100-hh/2})
                ddd.addPoint({x:100+ww/2,y:100+hh/2})
                ddd.piclink=base64;

                self.drButton.aBody=ddd;

                self.par.par.menu.mIBlok.mibLinsAnd.setBody(ddd);
                self.par.wScane.dragBig()
                self.galBody.drag(self.par.wScane.array)
                fun("dragScane"); 
            }
            img.src = base64;            
        }   


        window.addEventListener("paste",e=>{            
            if(self.dCont==undefined)return
            
            var items;
            if (e.clipboardData && e.clipboardData.items) {
                items = e.clipboardData.items;                
                if (items) {
                    items = Array.prototype.filter.call(items, function (element) {                        
                        return element.type.indexOf("image") >= 0;
                    });
                    self.stop();

                    Array.prototype.forEach.call(items, function (item) {                        
                        var blob = item.getAsFile();
                        var reader = new FileReader();
                        reader.onloadend = function (event) {                            
                            var s = event.target.result;
                            
                            self.plusPic(s)
                           // self.scane.setPic(s, self.chPic.value)                           
                        }                        
                        reader.readAsDataURL(blob);
                    })
                }
            }
        })

    }

    set aBody(value) { 
        
        if(this._aBody!==value){  
            this._aBody=value;
            this.drButton.aBody=value;
        }
        
    }   
    get aBody() { return  this._aBody}

    set metodType(value) { 
        if(this._metodType!=value){  
            this._metodType=value;
                 
        }
    }   
    get metodType() { return  this._metodType}
}


export class DRMenu {
    constructor(par,  fun) {
        var self=this
        this.type="DRButton";
        this._aBody=null
        this.par=par
        this.fun=fun;
        
        this._activMouse=true


        this.dC=new DCont(this.par.dCont);


        



        this.mS={x:0, y:0}
        this.index
        this.start=function(index){
            this.index=index;
            this.mS.x=9999999
           

            if (dcmParam.mobile == false) {
                document.addEventListener('mouseup', self.mouseup);
            } else {
                document.addEventListener('touchend', self.mouseup);
            }
            dcmParam.addFunMove(self.mousemove);
        }

        this.mouseup=function(e){
                    
            if (dcmParam.mobile == false) {
                document.removeEventListener('mouseup', self.mouseup);
            } else {
                document.removeEventListener('touchend', self.mouseup);
            }
            dcmParam.removeFunMove(self.mousemove);      
            self.par.par.wScane.dragBig()

        }

        this.mP={x:0, y:0}
        this.mousemove = function(e) {           
            self.par.getPoint(e,self.mP,true)

            if(self.mS.x==9999999){
                self.par.getPoint(e,self.mS,true)
            }
            //
            self.kirekt()
        }


        this.mPzz={x:0, y:0, dist:0}
        this.kirekt = function() { 
            this.mPzz.dist=this.getDistance(this.mP,self.mS)
            this.mPzz.x=this.mP.x-self.mS.x
            this.mPzz.y=this.mP.y-self.mS.y

            self.mS.x=this.mP.x;
            self.mS.y=this.mP.y;

            if(this.mPzz.dist==0)return
            if(this.index==0){//dvig
                this.par.par.wScane.setArrPoint(this.mPzz)
            }
            if(this.index==1){//dvig
                this.par.par.wScane.setArrRidation(this.mPzz.x)
            }
            if(this.index==2){//dvig
                this.par.par.wScane.setArrScale(this.mPzz.x)
            }
            if(this.index==3){//dvig
                this.par.par.wScane.setArrScale1(this.mPzz.x)
            }

            this.par.drButton.draw()
        }

        this.getDistance = function (p1, p2) {      
            return Math.sqrt(Math.pow((p1.x - p2.x), 2) + Math.pow((p1.y - p2.y), 2));
        };       
    }
}



export class DRButton {
    constructor(par,  fun) {
        var self=this
        this.type="DRButton";
        this._aBody=null
        this.par=par
        this.fun=fun;
        
        this._activMouse=true

        


        this.dC=new DCont(this.par.dCont);

        

        this._active=false;
        this.ols=this.par.ols;
        if(this.par.ols.bPoint==true)this._active=true;
        this.dCont=new DCont();
        if(this._active==true)this.dC.add(this.dCont)


        var dB=null
        this.sob=function(){
            if(self._active==false)return
            dB=this.dddCont

            

           
            if (dcmParam.mobile == false) {
                document.addEventListener('mouseup', self.mouseup);
            } else {
                document.addEventListener('touchend', self.mouseup);
            }
            dcmParam.addFunMove(self.mousemove);
        }

        this.mP={x:0, y:0}
        this.mousemove = function(e) {

           
            self.par.getPoint(e,self.mP) 
           
            dB.x=self.mP.x
            dB.y=self.mP.y
            dB.point.x=self.mP.x
            dB.point.y=self.mP.y

            if(dB && dB.body && dB.body.object && dB.body.object.type=="Text"){
                self.dragBody()
            }
            self.par.fun("dragScane");
        }

        this.mouseup=function(e){

            if (dcmParam.mobile == false) {
                document.removeEventListener('mouseup', self.mouseup);
            } else {
                document.removeEventListener('touchend', self.mouseup);
            }
            dcmParam.removeFunMove(self.mousemove);      
            dB=null
            self.par.par.wScane.dragBig()
        }



        this.array=[]
        this.sah=0
        var bbb
        var ppp
        var www=10
        this.creat=function(body, point, pozit){
            if(this.array[this.sah]==undefined) {
                this.array[this.sah]=new DCont(this.dCont)

                bbb=new DButton(this.array[this.sah],-www/2,-www/2,"")                
                bbb.idArr=this.sah
                bbb.width=www;
                bbb.height=www;
                bbb.borderRadius=www/2
                bbb.fun_mousedown=this.sob;
               // bbb.alpha=0.5;
                bbb.dddCont=this.array[this.sah]
                
            }
            
            ppp=this.array[this.sah];
            ppp.visible=true
            ppp.body=body
            ppp.point=point
            ppp.pozit=pozit 

            ppp.x=ppp.point.x;
            ppp.y=ppp.point.y;   

            this.sah++;
        }


        this.draw=function(){
            if(this._active==false)return
            if(dB!=null)return
             
            for (var i = 0; i < this.array.length; i++) {
                if(this.array[i].visible==false)return

                ppp=this.array[i];    
                ppp.x=ppp.point.x;
                ppp.y=ppp.point.y;      
            } 
        }



        this.clear=function(){
            this.sah=0
            for (var i = 0; i < this.array.length; i++) {
                this.array[i].visible=false
            }    
        }


        this.sArray=[];
        this.setArrBody=function(a){
            this.sArray=a;
            if(this._active==false)return
            this.clear()
            for (var i = 0; i < a.length; i++) {
                for (var j = 0; j < a[i].array.length; j++) {
                    this.creat(a[i],a[i].array[j],j)
                }                
            }
        }


        let r,ww;
        this.korText=function(){  

            this.textarea.fontSize=this._aBody.object.lineSah*4;
            this.textarea.object.style.lineHeight=this._aBody.object.lineSah*4+"px"
            self.textarea.width=100
            self.textarea.width=self.textarea.object.scrollWidth+this.textarea.fontSize
            self.textarea.height=10;            
            self.textarea.height=self.textarea.object.scrollHeight+this.textarea.fontSize
            
            
           
            setTimeout(function() {                
               // self.textarea.height=self.textarea.object.scrollHeight;
            }, 10);
        }

       this.textarea = new DTextArea(this.dC,0,0,"",function(){
            self._aBody.object.text=this.value
            self.korText()
          
            self.par.par.par.menu.mIBlok.mibLinsAnd.drag();
        })
        this.textarea.timeFun=1
        this.textarea.textAlign='left';
        this.textarea.object.style.whiteSpace = 'nowrap';
        this.textarea.object.style.background="transparent"
        this.textarea.alpha=0.5;
        this.textarea.fontFamily=self.par.par.par.rPar.fontFamily
        //this.textarea.object.style.color = "#ff0000";

        this.textarea.visible=false;

        var bbbb
        this.dragBody=function(){
            bbbb=false
            if(this._aBody==null){
                bbbb=false
            } else{
                if(this._aBody.object.type==="Text")bbbb=true; 
            } 
            if(bbbb==true /*&&  this.textarea.visible==false*/) {
                
                setTimeout(function() {
                    self.textarea.object.focus()
                }, 100);
                setTimeout(function() {
                    self.textarea.object.focus()
                }, 500);
                this.textarea.x=this._aBody.array[0].x;
                this.textarea.y=this._aBody.array[0].y;
            }          
            this.textarea.visible=bbbb;
                
            if(bbbb==true){
                this.textarea.value=this._aBody.object.text+"";
                this.textarea.fontSize=this._aBody.object.lineSah*4;
          
                this.korText()
            } 
        } 


    }

    set active(value) { 
        if(this._active!==value){  
            this._active=value;
            if(this._active){

                this.dC.add(this.dCont);
                this.setArrBody(this.sArray);
            }else{
                this.dC.remove(this.dCont);              
            }
        }
    }   
    get active() { return  this._active}



    set activMouse(value) { 
        if(this._activMouse!==value){  
            this._activMouse=value;
            if(this._activMouse){
                this.dCont.div.style.pointerEvents = null;   
            }else{
                this.dCont.div.style.pointerEvents = 'none';
              
            }
        }
    }   
    get activMouse() { return  this._activMouse}


    set aBody(value) {
        if(this._aBody!==value){  
            this._aBody=value;             
            if(this._aBody==null){
                this.setArrBody(this.par.par.wScane.array) 
            } else{
                this.setArrBody([this._aBody]) 

            } 
            this.dragBody()
        }
    }   
    get aBody() { return  this._aBody}
}


